import{_ as a,o as t,c as i,ah as r}from"./chunks/framework.DDXs_i7t.js";const m=JSON.parse('{"title":"Research: The Lawsuit Machine Dr. Michael Rami","description":"Documentation of systematic waves of lawsuits against private individuals and the role of Michael Rami as the legal executor of power.","frontmatter":{"title":"Research: The Lawsuit Machine Dr. Michael Rami","description":"Documentation of systematic waves of lawsuits against private individuals and the role of Michael Rami as the legal executor of power.","date":"2026-04-07T00:00:00.000Z"},"headers":[],"relativePath":"en/recherche/klagsmaschine-michael-rami.md","filePath":"en/recherche/klagsmaschine-michael-rami.md"}'),o={name:"en/recherche/klagsmaschine-michael-rami.md"};function n(s,e,h,l,c,u){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="research-the-lawsuit-machine-dr-michael-rami" tabindex="-1">Research: The Lawsuit Machine Dr. Michael Rami <a class="header-anchor" href="#research-the-lawsuit-machine-dr-michael-rami" aria-label="Permalink to &quot;Research: The Lawsuit Machine Dr. Michael Rami&quot;">​</a></h1><p>In our project, we investigate the instrumentalization of the judiciary to secure power structures. The case of Michael Rami is the prime example of this in the 21st century.</p><h2 id="the-business-model-warning-letters-as-intimidation" tabindex="-1">The Business Model: Warning Letters as Intimidation <a class="header-anchor" href="#the-business-model-warning-letters-as-intimidation" aria-label="Permalink to &quot;The Business Model: Warning Letters as Intimidation&quot;">​</a></h2><p>Michael Rami (Constitutional Judge and media lawyer) launched a wave of lawsuits on behalf of <strong>Katharina Nehammer</strong> that is unprecedented in Austria.</p><h3 id="_1-the-4-500-euro-bill" tabindex="-1">1. The &quot;4,500 Euro Bill&quot; <a class="header-anchor" href="#_1-the-4-500-euro-bill" aria-label="Permalink to &quot;1. The &quot;4,500 Euro Bill&quot;&quot;">​</a></h3><p>The strategy is simple but devastating: Hundreds of private individuals receive standardized warning letters.</p><ul><li><strong>Demand:</strong> 3,500 Euro compensation (for Katharina Nehammer) + approx. 940 Euro legal costs (for Rami).</li><li><strong>Reason:</strong> Simply sharing a Facebook post (e.g., about the <em>Hygiene Austria</em> case).</li><li><strong>Target Group:</strong> It specifically hit <strong>minimum pensioners, students, and low earners</strong>. Many paid out of pure fear of even higher court costs.</li></ul><h3 id="_2-the-case-of-the-61-year-old-carinthian" tabindex="-1">2. The Case of the 61-year-old Carinthian <a class="header-anchor" href="#_2-the-case-of-the-61-year-old-carinthian" aria-label="Permalink to &quot;2. The Case of the 61-year-old Carinthian&quot;">​</a></h3><p>One documented case concerned a man from Klagenfurt who had merely shared a critical post. Rami forced him into an expensive settlement and public revocation. Critics call this <strong>SLAPP</strong> (Strategic Lawsuit Against Public Participation) – a lawsuit intended only to financially ruin and silence critics.</p><h2 id="the-double-role-of-the-villain" tabindex="-1">The Double Role of the &quot;Villain&quot; <a class="header-anchor" href="#the-double-role-of-the-villain" aria-label="Permalink to &quot;The Double Role of the &quot;Villain&quot;&quot;">​</a></h2><p>What makes Rami so valuable as a &quot;system villain&quot; for our project is his dual function:</p><ul><li><strong>The High Judge:</strong> By day, he decides on the constitutionality of laws at the Constitutional Court (VfGH, nominated by the FPÖ).</li><li><strong>The Elite Lawyer:</strong> By night, he uses his legal weight to sue the critics of the Chancellor&#39;s family or FPÖ greats (such as Strache or Kickl).</li></ul><h3 id="the-scientific-washing-of-the-advertisement-affair" tabindex="-1">The &quot;Scientific Washing&quot; of the Advertisement Affair <a class="header-anchor" href="#the-scientific-washing-of-the-advertisement-affair" aria-label="Permalink to &quot;The &quot;Scientific Washing&quot; of the Advertisement Affair&quot;">​</a></h3><p>Currently (April 2026), Rami is attempting to prove through a <strong>WU study</strong> in the advertisement affair (Eva Dichand) that corruption statistically did not take place at all. It is the continuation of his strategy: when chats become too overwhelming, he strikes back with expert opinions and lawsuits.</p><h2 id="significance-for-the-horten-mystery" tabindex="-1">Significance for the Horten Mystery <a class="header-anchor" href="#significance-for-the-horten-mystery" aria-label="Permalink to &quot;Significance for the Horten Mystery&quot;">​</a></h2><p>Rami is the modern equivalent of the lawyers of &quot;Aryanization.&quot; He doesn&#39;t burn files; he suffocates the truth in a mountain of lawsuit threats and fee schedules.</p><p><em>The index of power is rising. We document the costs of truth.</em></p><hr><p><em>Sources: Kurier, Krone, Kleine Zeitung (as of April 07, 2026), court records of the Nehammer lawsuit wave.</em></p>',19)])])}const f=a(o,[["render",n]]);export{m as __pageData,f as default};
